contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(uint val1, uint val2) public {
        c.SetMinSum(val1); if (__ESBMC_reverted()) return;
        uint m1 = c.MinSum(); if (__ESBMC_reverted()) return;
        c.SetLogFile(address(this)); if (__ESBMC_reverted()) return;
        c.SetMinSum(val2); if (__ESBMC_reverted()) return;
        uint m2 = c.MinSum(); if (__ESBMC_reverted()) return;
        assert(m1 == val1 && m2 == val2);
    }
    receive() external payable {}
}

