pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PENNY_BY_PENNY} from "../src/PENNY_BY_PENNY.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PENNY_BY_PENNY c;

    function setUp() public {
        c = new PENNY_BY_PENNY();
    }

    function _run(uint256 val1, uint256 val2) internal {
        try c.SetMinSum(val1) {} catch { return; }
        uint256 m1;
        try c.MinSum() returns (uint256 __r) { m1 = __r; } catch { return; }
        try c.SetLogFile(address(this)) {} catch { return; }
        try c.SetMinSum(val2) {} catch { return; }
        uint256 m2;
        try c.MinSum() returns (uint256 __r) { m2 = __r; } catch { return; }
        assertTrue(m1 == val1 && m2 == val2);
    }

    function testFuzz_run(uint256 val1, uint256 val2) public {
        _run(val1, val2);
    }

    receive() external payable {}
}
